for(const weight of[100,349,350,549,550,749,750,900])for(const relative of['bolder','lighter']){document.body.innerHTML='<div id=p><span id=c>x</span></div>';const p=document.getElementById('p'),c=document.getElementById('c');p.style.fontWeight=String(weight);c.style.fontWeight=relative;rows.push({weight,relative,computed:getComputedStyle(c).fontWeight,authored:c.style.fontWeight});}
